from pathlib import Path
s=Path('experiments/gather/pair_v1.py').read_text()
s=s.replace('__launch_bounds__(288,2)','__launch_bounds__(160,3)').replace('<<<grid,288,0,stream>>>','<<<grid,160,0,stream>>>')
s=s.replace('asm volatile("bar.sync %0, 128;"::"r"(wg+1):"memory");','asm volatile("bar.sync 1, 128;":::"memory");')
s=s.replace('unsigned ready[STAGES][2];','unsigned ready[STAGES];')
s=s.replace('const unsigned global_tid=threadIdx.x, wg=global_tid/128, tid=global_tid%128, warp=tid/32, lane=tid%32;','const unsigned tid=threadIdx.x, warp=tid/32, lane=tid%32;')
s=s.replace('h=blockIdx.z*2+wg, split=blockIdx.x','h=blockIdx.z*2, split=blockIdx.x')
s=s.replace('for(int i=global_tid;i<STAGES*2;i+=blockDim.x) ((unsigned*)ready)[i]=0;','if(tid<STAGES)ready[tid]=0;')
s=s.replace('if(wg<2) for(int row=warp;row<M;row+=4) {','for(int wg=0;wg<2;wg++) for(int row=warp;row<M;row+=5) {')
s=s.replace('head=h*G+row%G','head=(h+wg)*G+row%G')
s=s.replace('if(wg<2 && split==0) for(int row=warp;row<8;row+=4) {','if(split==0) for(int wg=0;wg<2;wg++) for(int row=warp;row<8;row+=5) {')
s=s.replace('(HQ+h)*D','(HQ+h+wg)*D').replace('(HQ+HKV+h)*D','(HQ+HKV+h+wg)*D').replace('loc[tok]*HKV*D+h*D','loc[tok]*HKV*D+(h+wg)*D')
s=s.replace('if(wg==2)','if(warp==4)')
s=s.replace('if(lane==0) { release(&ready[consumed%STAGES][0],1); release(&ready[consumed%STAGES][1],1); }','if(lane==0)release(ready+consumed%STAGES,1);')
s=s.replace('while(acquire(&ready[stage][0])!=0 || acquire(&ready[stage][1])!=0)','while(acquire(ready+stage)!=0)')
s=s.replace('wmma::fragment<wmma::accumulator,16,16,16,float> acc[4];','wmma::fragment<wmma::accumulator,16,16,16,float> acc[2][4];')
s=s.replace('for(int n=0;n<4;n++) wmma::fill_fragment(acc[n],0.f);','for(int hh=0;hh<2;hh++) {\n  #pragma unroll\n  for(int n=0;n<4;n++) wmma::fill_fragment(acc[hh][n],0.f);\n }')
s=s.replace('float mx[2]={-1e30f,-1e30f}, sum[2]={0,0};','float mx[2][2]={{-1e30f,-1e30f},{-1e30f,-1e30f}}, sum[2][2]={{0,0},{0,0}};')
s=s.replace('unsigned q[2][4];','unsigned q[2][2][4];\n #pragma unroll\n for(int wg=0;wg<2;wg++) {')
s=s.replace('q[d][i]=','q[wg][d][i]=')
s=s.replace(' for(int tile=0;tile<tiles;tile++) {',' }\n for(int tile=0;tile<tiles;tile++) {')
s=s.replace('while(acquire(&ready[stage][wg])!=1)','while(acquire(ready+stage)!=1)')
s=s.replace('   #pragma unroll\n   for(unsigned j=0;j<N*D/256;j++) {','   #pragma unroll\n   for(int wg=0;wg<2;wg++) {\n   #pragma unroll\n   for(unsigned j=0;j<N*D/256;j++) {')
s=s.replace('q[d][0]','q[wg][d][0]').replace('q[d][1]','q[wg][d][1]').replace('q[d][2]','q[wg][d][2]').replace('q[d][3]','q[wg][d][3]')
s=s.replace('mx[r]','mx[wg][r]').replace('sum[r]','sum[wg][r]').replace('acc[n]','acc[wg][n]')
s=s.replace('   if(tid==0) release(&ready[stage][wg],0);','   }\n   if(tid==0) release(ready+stage,0);')
s=s.replace(' long base=((long)(b*HKV+h)*SPLITS+split)*M;',' #pragma unroll\n for(int wg=0;wg<2;wg++) {\n long base=((long)(b*HKV+h+wg)*SPLITS+split)*M;')
s=s.replace('\n}\nvoid attention','\n }\n}\nvoid attention')
s=s.replace("'.build-pair'","'.build-dual'").replace('codex_verify_pair3','codex_verify_dual3')
s=s.replace('else if(stages==5) { LAUNCH(3,','else if(stages==5) { LAUNCH(5,').replace('else if(stages==6) { LAUNCH(3,','else if(stages==6) { LAUNCH(6,')
Path('experiments/gather/dual.py').write_text(s)
s=Path('experiments/gather/bench_pair.py').read_text().replace('import pair','import dual as pair').replace('results/pair-{batch}','results/dual-{batch}').replace('(1,16,32)','(16,32)').replace('(2,3),(132,264,396,528,792)','(3,4,5),(264,396,528,792)')
Path('experiments/gather/bench_dual.py').write_text(s)
